+/** Theoretical sales use and actual consumption per item, in inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  const totals = new Map();
+  const add = (itemId, field, qty) => {
+    const entry = totals.get(itemId) ?? { itemId, theoretical: 0, actual: 0 };
+    entry[field] += Math.round(qty * 1000);
+    totals.set(itemId, entry);
+  };
+  for (const sale of store.data.sales) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day >= from && day <= to) for (const ingredient of sale.ingredients) add(ingredient.itemId, "theoretical", ingredient.qty);
+  }
+  for (const movement of store.data.movements) {
+    const day = new Date(movement.at).toISOString().slice(0, 10);
+    if (movement.type !== "consume" || day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === movement.batchId);
+    if (batch) add(batch.itemId, "actual", movement.qty);
+  }
+  return [...totals.values()].filter((entry) => entry.theoretical > 0 || entry.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId)
+    .map(({ itemId, theoretical, actual }) => ({ itemId, theoretical: theoretical / 1000, actual: actual / 1000, difference: (actual - theoretical) / 1000 }));
+}
